"""Verify the G2/G3 commands generated by Gcode.arc_move. Run with:
python3 -m unittest testing.unit_tests.arc_move"""

import unittest

from svg_to_gcode.compiler.interfaces import Gcode


class ArcMoveTest(unittest.TestCase):

    def setUp(self):
        # Every test starts with the tool at (0, 0). An arc needs a known start point.
        self.gcode = Gcode()
        self.gcode.set_movement_speed(1000)
        self.gcode.linear_move(0, 0)

    def test_clockwise_and_counter_clockwise(self):
        # G2 is clockwise, G3 is counter-clockwise. I and J are offsets from the start to the center.
        self.assertEqual(self.gcode.arc_move(10, 0, 5, 0, True), "G2 X10.000000 Y0.000000 I5.000000 J0.000000;")
        self.assertEqual(self.gcode.arc_move(0, 0, -5, 0, False), "G3 X0.000000 Y0.000000 I-5.000000 J0.000000;")

    def test_position_follows_the_arc(self):
        # The next move starts where the arc ended, so the interface must remember the end of the arc.
        self.gcode.arc_move(10, 0, 5, 0, True)
        self.assertEqual((self.gcode.position.x, self.gcode.position.y), (10, 0))

    def test_feed_rate_is_sent_once(self):
        # F is written when the speed changes, and then omitted: the first move after set_movement_speed(300) has F300,
        # the next one doesn't.
        gcode = Gcode()
        gcode.set_movement_speed(1000)
        gcode.linear_move(0, 0)
        gcode.set_movement_speed(300)

        self.assertIn("F300", gcode.arc_move(10, 0, 5, 0, True))
        self.assertNotIn("F", gcode.arc_move(0, 0, -5, 0, True))

    def test_same_end_point_is_a_line(self):
        # GRBL would draw a full circle
        self.assertTrue(self.gcode.arc_move(0.0000001, 0, 5, 0, True).startswith("G1"))

    def test_zero_center_offset_is_a_line(self):
        # GRBL rejects an arc with no radius
        self.assertTrue(self.gcode.arc_move(5, 5, 0.0000001, 0, True).startswith("G1"))

    def test_unknown_position(self):
        # Without a start point the center offset can't be interpreted.
        with self.assertRaises(ValueError):
            Gcode().arc_move(1, 1, 1, 1, True)


if __name__ == "__main__":
    unittest.main()
